"use strict";

const { match } = require("arktype");

/**
 * Unit converter built on ArkType's `match` API.
 *
 * Each case is an ArkType definition string (the key) paired with a handler
 * that converts the matched metric value into a formatted imperial-unit string.
 *
 * `default: "assert"` guarantees exhaustiveness: any input that does not match
 * one of the declared cases causes the matcher to throw.
 */
const convert = match({
  '{ kind: "length", meters: "number" }': (o) =>
    `${(o.meters * 3.28084).toFixed(2)} ft`,

  '{ kind: "mass", kilograms: "number" }': (o) =>
    `${(o.kilograms * 2.20462).toFixed(2)} lb`,

  '{ kind: "temperature", celsius: "number" }': (o) =>
    `${((o.celsius * 9) / 5 + 32).toFixed(2)} °F`,

  default: "assert",
});

// ---------------------------------------------------------------------------
// Read a single JSON object from STDIN, dispatch it through the matcher,
// and print the resulting imperial-unit string to STDOUT.
// ---------------------------------------------------------------------------
let raw = "";

process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  raw += chunk;
});

process.stdin.on("end", () => {
  try {
    const input = JSON.parse(raw);
    const result = convert(input);
    console.log(result);
  } catch (err) {
    console.error(err.message || err);
    process.exit(1);
  }
});

